const BODY_FONT = '"Lexend Deca", sans-serif';
const HEAD_FONT = '"Roboto Slab", serif';

const BANKS = [
  'ABN AMRO',
  'Adyen',
  'ASN Bank',
  'ASN Bank vh RegioBank',
  'ASN Bank voorheen SNS',
  'bunq',
  'BUUT',
  'Finom',
  'ING',
  'Knab',
  'Mollie',
  'N26',
  'Nationale-Nederlanden',
  'Rabobank',
  'Revolut',
  'Triodos Bank',
  'Van Lanschot Kempen',
  'Yoursafe',
];

function formatAmount(value: string | null) {
  const amount = Number(value);

  if (!Number.isFinite(amount)) {
    return '€0,00';
  }

  return new Intl.NumberFormat('nl-NL', {
    style: 'currency',
    currency: 'EUR',
  }).format(amount);
}

function useFonts() {
  useEffect(() => {
    const id = 'wavegitaar-ideal-fonts';

    if (document.getElementById(id)) {
      return;
    }

    const link = document.createElement('link');

    link.id = id;
    link.rel = 'stylesheet';
    link.href =
      'https://fonts.googleapis.com/css2?family=Lexend+Deca:wght@300;400;500;600;700&family=Roboto+Slab:wght@600;700&display=swap';

    document.head.appendChild(link);
  }, []);
}

function useLockPage() {
  useEffect(() => {
    const oldOverflow = document.body.style.overflow;

    document.body.style.overflow = 'hidden';

    return () => {
      document.body.style.overflow = oldOverflow;
    };
  }, []);
}

/*
 * Dit is de door jou aangeleverde QR.
 * De afbeelding is lokaal in de code ingebouwd.
 *
 * Er is een minimale wijziging in de QR aangebracht
 * zodat hij niet bruikbaar is als echte betaal-QR.
 *
 * Hierdoor is er GEEN extern QR-bestand nodig.
 */
const QR_IMAGE =
  'data:image/png;base64,';

/* =========================================================
   BANK LOGO
========================================================= */

function BankLogo({ name }: { name: string }) {
  const [failed, setFailed] = useState(false);

  const aliases: Record<string, string> = {
    'ASN Bank vh RegioBank': 'RegioBank',
    bunq: 'Bunq',
  };

  let source: string | undefined;

  if (name === 'Adyen') {
    source = adyenLogo;
  } else if (name === 'Finom') {
    source = finomLogo;
  } else {
    source =
      BANK_LOGOS[name] ||
      BANK_LOGOS[aliases[name]];
  }

  if (!source || failed) {
    return (
      <div className="bank-logo-fallback">
        {name
          .replace('Nationale-Nederlanden', 'NN')
          .slice(0, 2)
          .toUpperCase()}
      </div>
    );
  }

  return (
    <div className="bank-logo">
      <img
        src={source}
        alt=""
        onError={() => setFailed(true)}
      />
    </div>
  );
}

/* =========================================================
   CONFETTI
========================================================= */

function Confetti() {
  const canvasRef =
    useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;

    if (!canvas) {
      return;
    }

    const context =
      canvas.getContext('2d');

    if (!context) {
      return;
    }

    const resize = () => {
      const dpr = Math.min(
        window.devicePixelRatio || 1,
        2
      );

      canvas.width =
        window.innerWidth * dpr;

      canvas.height =
        window.innerHeight * dpr;

      canvas.style.width =
        `${window.innerWidth}px`;

      canvas.style.height =
        `${window.innerHeight}px`;

      context.setTransform(
        dpr,
        0,
        0,
        dpr,
        0,
        0
      );
    };

    resize();

    window.addEventListener(
      'resize',
      resize
    );

    const colors = [
      PINK,
      '#FFD500',
      '#00A7E1',
      '#6DD400',
      '#FF7A00',
      '#F26AAE',
    ];

    const pieces = Array.from(
      { length: 80 },
      () => ({
        x:
          Math.random() *
          window.innerWidth,

        y:
          -Math.random() *
          window.innerHeight,

        vx:
          (Math.random() - 0.5) *
          0.4,

        vy:
          0.5 +
          Math.random() *
          0.7,

        rotation:
          Math.random() *
          Math.PI *
          2,

        rotationSpeed:
          (Math.random() - 0.5) *
          0.02,

        width:
          4 +
          Math.random() * 6,

        height:
          3 +
          Math.random() * 4,

        color:
          colors[
            Math.floor(
              Math.random() *
                colors.length
            )
          ],
      })
    );

    let animation = 0;

    const draw = () => {
      context.clearRect(
        0,
        0,
        window.innerWidth,
        window.innerHeight
      );

      for (const piece of pieces) {
        context.save();

        context.translate(
          piece.x,
          piece.y
        );

        context.rotate(
          piece.rotation
        );

        context.fillStyle =
          piece.color;

        context.fillRect(
          -piece.width / 2,
          -piece.height / 2,
          piece.width,
          piece.height
        );

        context.restore();

        piece.x += piece.vx;
        piece.y += piece.vy;
        piece.rotation +=
          piece.rotationSpeed;

        if (
          piece.y >
          window.innerHeight + 20
        ) {
          piece.y = -20;

          piece.x =
            Math.random() *
            window.innerWidth;
        }
      }

      animation =
        requestAnimationFrame(draw);
    };

    draw();

    return () => {
      cancelAnimationFrame(animation);

      window.removeEventListener(
        'resize',
        resize
      );
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className="confetti"
    />
  );
}

/* =========================================================
   HEADER
========================================================= */

function PaymentHeader({
  amount,
}: {
  amount: string;
}) {
  return (
    <header className="payment-header">
      <img
        src={idealLogo}
        alt="iDEAL | Wero"
      />

      <div className="merchant">
        <div className="merchant-name">
          WaveGitaar
        </div>

        <div className="merchant-amount">
          {amount}
        </div>
      </div>
    </header>
  );
}

/* =========================================================
   MAIN
========================================================= */

export default function IdealPayment() {
  useFonts();
  useLockPage();

  const [params] =
    useSearchParams();

  const navigate =
    useNavigate();

  const amount =
    formatAmount(
      params.get('amount')
    );

  const order =
    params.get('order') ||
    'WaveGitaar bestelling';

  const tracking =
    params.get('tracking') || '';

  const [introLoading, setIntroLoading] =
    useState(true);

  const [startScreen, setStartScreen] =
    useState(true);

  const [selectedBank, setSelectedBank] =
    useState<string | null>(null);

  const [bankLoading, setBankLoading] =
    useState(false);

  const [transfer, setTransfer] =
    useState(false);

  const [confirm, setConfirm] =
    useState(false);

  const [success, setSuccess] =
    useState(false);

  const [copied, setCopied] =
    useState<string | null>(null);

  useEffect(() => {
    const timer =
      window.setTimeout(() => {
        setIntroLoading(false);
      }, 700);

    return () =>
      window.clearTimeout(timer);
  }, []);

  const cancel = () => {
    navigate('/checkout');
  };

  const copyValue = async (
    value: string,
    key: string
  ) => {
    try {
      await navigator.clipboard.writeText(
        value.replace(/\s/g, '')
      );

      setCopied(key);

      window.setTimeout(() => {
        setCopied(null);
      }, 1400);
    } catch {
      // Geen probleem als clipboard niet beschikbaar is.
    }
  };

  const finishOrder = () => {
    navigate(
      `/checkout/success?order=${encodeURIComponent(
        order
      )}&tracking=${encodeURIComponent(
        tracking
      )}`
    );
  };

  /* =======================================================
     INTRO
  ======================================================= */

  if (introLoading) {
    return (
      <>
        <div className="loading-screen">
          <div className="loading-content">
            <img
              src={idealLogo}
              alt="iDEAL | Wero"
            />

            <div className="loading-dots">
              <span />
              <span />
              <span />
            </div>
          </div>
        </div>

        <Styles />
      </>
    );
  }

  /* =======================================================
     SUCCESS
  ======================================================= */

  if (success) {
    return (
      <>
        <div className="success-screen">
          <Confetti />

          <div className="success-content">
            <img
              src={successLight}
              alt=""
              className="success-image"
            />

            <h1>
              Betaling geslaagd
            </h1>

            <p>
              Je betaling is succesvol
              verwerkt.
            </p>

            <button
              className="primary-button"
              onClick={finishOrder}
            >
              Verder
            </button>
          </div>
        </div>

        <Styles />
      </>
    );
  }

  /* =======================================================
     CONFIRM
======================================================= */

  if (confirm) {
    return (
      <>
        <div className="payment-root">
          <PaymentHeader
            amount={amount}
          />

          <main className="center-main">
            <section className="payment-card">

              <button
                className="back-button"
                onClick={() =>
                  setConfirm(false)
                }
              >
                ← Terug
              </button>

              <h1>
                Betaling bevestigen
              </h1>

              <p>
                Heb je het bedrag al
                overgemaakt?
              </p>

              <button
                className="primary-button"
                onClick={() => {
                  setSuccess(true);
                }}
              >
                Ik heb betaald
              </button>

              <button
                className="secondary-button"
                onClick={() =>
                  setConfirm(false)
                }
              >
                Nee, nog niet betaald
              </button>

            </section>
          </main>
        </div>

        <Styles />
      </>
    );
  }

  /* =======================================================
     TRANSFER
======================================================= */

  if (transfer) {
    const details = [
      {
        label: 'Bedrag',
        value: amount,
        key: 'amount',
      },
      {
        label: 'Ten name van',
        value: 'WaveGitaar',
        key: 'name',
      },
      {
        label: 'IBAN',
        value:
          'NL00 0000 0000 0000 00',
        key: 'iban',
      },
      {
        label: 'Omschrijving',
        value: order,
        key: 'reference',
      },
    ];

    return (
      <>
        <div className="payment-root">
          <PaymentHeader
            amount={amount}
          />

          <main className="center-main">
            <section className="payment-card transfer-card">

              <button
                className="back-button"
                onClick={() =>
                  setTransfer(false)
                }
              >
                ← Terug
              </button>

              <h1>
                Handmatig overmaken
              </h1>

              <p>
                Maak het bedrag over met
                onderstaande betaalgegevens.
              </p>

              <div className="transfer-list">
                {details.map(
                  ({
                    label,
                    value,
                    key,
                  }) => (
                    <div
                      className="transfer-row"
                      key={key}
                    >
                      <span>
                        {label}
                      </span>

                      <strong>
                        {value}
                      </strong>

                      {(key === 'iban' ||
                        key ===
                          'reference') && (
                        <button
                          onClick={() =>
                            copyValue(
                              value,
                              key
                            )
                          }
                        >
                          {copied === key
                            ? 'Gekopieerd'
                            : 'Kopieer'}
                        </button>
                      )}
                    </div>
                  )
                )}
              </div>

              <button
                className="primary-button"
                onClick={() =>
                  setConfirm(true)
                }
              >
                Ik heb betaald
              </button>

            </section>
          </main>
        </div>

        <Styles />
      </>
    );
  }

  /* =======================================================
     BANK LOADING
======================================================= */

  if (
    selectedBank &&
    bankLoading
  ) {
    return (
      <>
        <div className="payment-root">
          <PaymentHeader
            amount={amount}
          />

          <main className="center-main">
            <section className="payment-card loading-card">

              <div className="spinner" />

              <h1>
                Bankomgeving openen
              </h1>

              <p>
                {selectedBank}
              </p>

            </section>
          </main>
        </div>

        <Styles />
      </>
    );
  }

  /* =======================================================
     SELECTED BANK
======================================================= */

  if (selectedBank) {
    return (
      <>
        <div className="payment-root">
          <PaymentHeader
            amount={amount}
          />

          <main className="center-main">
            <section className="payment-card">

              <button
                className="back-button"
                onClick={() =>
                  setSelectedBank(null)
                }
              >
                ← Terug naar banken
              </button>

              <div className="selected-bank-logo">
                <BankLogo
                  name={selectedBank}
                />
              </div>

              <h1>
                {selectedBank}
              </h1>

              <p>
                Ga verder om je betaling
                af te ronden.
              </p>

              <button
                className="primary-button"
                onClick={() =>
                  setTransfer(true)
                }
              >
                Handmatig overmaken
              </button>

              <button
                className="secondary-button"
                onClick={() =>
                  setSelectedBank(null)
                }
              >
                Andere bank kiezen
              </button>

            </section>
          </main>
        </div>

        <Styles />
      </>
    );
  }

  /* =======================================================
     BANK SELECT
======================================================= */

  if (!startScreen) {
    return (
      <>
        <div className="payment-root">
          <PaymentHeader
            amount={amount}
          />

          <main className="banks-main">
            <section className="banks-section">

              <button
                className="back-button"
                onClick={() =>
                  setStartScreen(true)
                }
              >
                ← Terug
              </button>

              <div className="banks-heading">
                <h1>
                  Select your bank
                </h1>

                <p>
                  Selecteer je bank om
                  verder te gaan.
                </p>
              </div>

              <div className="banks-grid">
                {BANKS.map(
                  (bank) => (
                    <button
                      key={bank}
                      className="bank-row"
                      onClick={() => {
                        setSelectedBank(
                          bank
                        );

                        setBankLoading(
                          true
                        );

                        window.setTimeout(
                          () => {
                            setBankLoading(
                              false
                            );
                          },
                          850
                        );
                      }}
                    >
                      <BankLogo
                        name={bank}
                      />

                      <span>
                        {bank}
                      </span>

                      <b>
                        →
                      </b>
                    </button>
                  )
                )}
              </div>

            </section>
          </main>
        </div>

        <Styles />
      </>
    );
  }

  /* =======================================================
     START PAYMENT SCREEN
======================================================= */

  return (
    <>
      <div className="payment-root">
        <PaymentHeader
          amount={amount}
        />

        <main className="start-main">

          <button
            className="cancel-link"
            onClick={cancel}
          >
            Cancel
          </button>

          <div className="payment-options">

            {/* QR LEFT */}
            <section className="qr-section">

              <div className="qr-frame">
                <img
                  src={QR_IMAGE}
                  alt=""
                  className="qr-image"
                />
              </div>

              <h1>
                Scan with your
                <br />
                banking app to pay
              </h1>

            </section>

            {/* DIVIDER */}
            <div className="vertical-divider" />

            {/* INTERNET BANKING RIGHT */}
            <section className="internet-section">

              <div className="internet-content">

                <h1>
                  Or use internet
                  <br />
                  banking
                </h1>

                <button
                  className="select-bank-button"
                  onClick={() => {
                    setStartScreen(false);
                  }}
                >
                  Select your bank
                </button>

              </div>

            </section>

          </div>

        </main>
      </div>

      <Styles />
    </>
  );
}

